ALTER TABLE "rental_bills" DROP CONSTRAINT "rental_bills_period_check", ADD CONSTRAINT "rental_bills_period_check" CHECK (("type"::text = 'deposit' AND "period_start" IS NULL AND "period_end" IS NULL AND "effective_end" IS NULL) OR ("type"::text = 'period' AND "period_start" IS NOT NULL AND "period_end" IS NOT NULL AND "period_end" >= "period_start" AND "effective_end" IS NOT NULL AND "effective_end" BETWEEN "period_start" AND "period_end"));